CREATE TABLE telemetry_readings(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,charger_id BINARY(16) NOT NULL,connector_id BINARY(16) NOT NULL,session_id BINARY(16),transaction_id VARCHAR(100),measurand VARCHAR(100) NOT NULL,value DECIMAL(20,6) NOT NULL,unit VARCHAR(30) NOT NULL,phase VARCHAR(30),context VARCHAR(50),location VARCHAR(30),sampled_at TIMESTAMP(6) NOT NULL,received_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_telemetry_charger_sampled ON telemetry_readings(charger_id,sampled_at);CREATE INDEX idx_telemetry_connector_sampled ON telemetry_readings(connector_id,sampled_at);CREATE INDEX idx_telemetry_session ON telemetry_readings(session_id);
